"use client";

import { useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { FlutedLayer } from "./fluted-glass/fluted-layer";
import { SlideCaption } from "./fluted-glass/slide-caption";
import { SlideControls } from "./fluted-glass/slide-controls";
import { SlideProgress } from "./fluted-glass/slide-progress";
import { DEFAULT_SLIDES, type Slide } from "./fluted-glass/slides";
import { usePageHidden, useSlideshow } from "./fluted-glass/use-slideshow";

// Cortexcn item "gallery-fluted-glass-01", revision 1290ed066905, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-fluted-glass-01/1290ed066905.json

export type { Slide } from "./fluted-glass/slides";

export interface FlutedGlassSlideshowProps {
  slides?: Slide[];
  /** Seconds each slide stays while the slideshow plays. */
  interval?: number;
  /** Vertical ribs in the glass. Fewer, wider ribs bend the picture more. */
  flutes?: number;
  /** Moves on by itself. Always off for visitors who prefer less motion. */
  autoPlay?: boolean;
  /** Names the slideshow for screen readers. */
  label?: string;
  className?: string;
}

/**
 * A wide slideshow where each new slide arrives through fluted glass: cut
 * into vertical ribs that bend it, which clear one after another as it lands.
 * It plays on its own; pointing at it holds it, and focus inside or the
 * pause button stops it until Play is pressed. Arrow keys, the previous and
 * next buttons, and the bars along the bottom move between slides.
 */
export function FlutedGlassSlideshow({
  slides = DEFAULT_SLIDES,
  interval = 6,
  flutes = 24,
  autoPlay = true,
  label = "Paintings",
  className,
}: FlutedGlassSlideshowProps) {
  const show = useSlideshow(slides.length);
  const reduceMotion = useReducedMotion();
  const pageHidden = usePageHidden();
  const [userPaused, setUserPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  /** Play pressed while focus is inside, which overrides the focus pause. */
  const [resumed, setResumed] = useState(false);

  const autoplay = autoPlay && reduceMotion === false && slides.length > 1;
  // Focus inside stops it until Play is pressed; pointing at it only holds it.
  const paused = userPaused || (focused && !resumed);
  const playing = autoplay && !paused && !hovered && !pageHidden;

  const rootRef = useRef<HTMLElement>(null);
  const moves = useRef({ next: show.next, previous: show.previous });
  moves.current = { next: show.next, previous: show.previous };

  // Arrow keys move between slides, focus inside stops autoplay until Play
  // is pressed, and pointing at the slideshow holds it.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) {
      return;
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "ArrowRight") {
        event.preventDefault();
        moves.current.next();
      } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        moves.current.previous();
      }
    };
    const onFocusIn = () => setFocused(true);
    const onFocusOut = (event: FocusEvent) => {
      if (!root.contains(event.relatedTarget as Node | null)) {
        setFocused(false);
        setResumed(false);
      }
    };
    const onEnter = () => setHovered(true);
    const onLeave = () => setHovered(false);
    root.addEventListener("keydown", onKeyDown);
    root.addEventListener("focusin", onFocusIn);
    root.addEventListener("focusout", onFocusOut);
    root.addEventListener("pointerenter", onEnter);
    root.addEventListener("pointerleave", onLeave);
    return () => {
      root.removeEventListener("keydown", onKeyDown);
      root.removeEventListener("focusin", onFocusIn);
      root.removeEventListener("focusout", onFocusOut);
      root.removeEventListener("pointerenter", onEnter);
      root.removeEventListener("pointerleave", onLeave);
    };
  }, []);

  // Loads every picture up front, so no slide waits on the network mid-change.
  useEffect(() => {
    for (const slide of slides) {
      const image = new Image();
      image.src = slide.src;
    }
  }, [slides]);

  const slide = slides[show.current];
  const base = slides[show.base];
  if (!(slide && base)) {
    return null;
  }

  const change = show.change;
  const arriving = change ? slides[change.to] : undefined;

  const togglePause = () => {
    if (paused) {
      setUserPaused(false);
      setResumed(true);
    } else {
      setUserPaused(true);
    }
  };

  return (
    <section
      aria-label={label}
      aria-roledescription="carousel"
      className={cn("w-full", className)}
      ref={rootRef}
    >
      <div className="relative aspect-4/3 w-full overflow-hidden rounded-2xl bg-muted sm:aspect-video lg:aspect-21/9">
        {/* biome-ignore lint/performance/noImgElement: framework-agnostic registry block */}
        <img
          alt=""
          className="absolute inset-0 size-full object-cover"
          decoding="async"
          draggable={false}
          height={base.height}
          src={base.src}
          width={base.width}
        />
        {change && arriving ? (
          <FlutedLayer
            direction={change.direction}
            flutes={flutes}
            key={change.id}
            onSettled={() => show.settle(change.id)}
            slide={arriving}
          />
        ) : null}

        {/* Keeps the caption and controls readable on light pictures. */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 bottom-0 h-3/4 bg-linear-to-t from-black/70 via-black/25 to-transparent"
        />

        <div className="absolute inset-x-0 bottom-0 flex flex-col gap-3 p-4 sm:gap-4 sm:p-6 lg:p-8">
          <div className="flex items-end justify-between gap-4">
            {/* biome-ignore lint/a11y/useSemanticElements: a carousel slide is a labeled group, not a form fieldset */}
            <div
              aria-label={`${show.current + 1} of ${slides.length}`}
              aria-live={playing ? "off" : "polite"}
              aria-roledescription="slide"
              className="min-w-0"
              role="group"
            >
              <SlideCaption
                count={slides.length}
                index={show.current}
                slide={slide}
              />
              <p className="sr-only">{slide.alt}</p>
            </div>
            <SlideControls
              autoplay={autoplay}
              onNext={show.next}
              onPrevious={show.previous}
              onTogglePause={togglePause}
              paused={paused}
            />
          </div>
          <SlideProgress
            autoplay={autoplay}
            current={show.current}
            onDone={show.next}
            onSelect={(index) => show.goTo(index)}
            playing={playing}
            seconds={interval}
            slides={slides}
          />
        </div>
      </div>
    </section>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { Slide } from "./slides";
import type { Direction } from "./use-slideshow";

// Cortexcn item "gallery-fluted-glass-01", revision 1290ed066905, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-fluted-glass-01/1290ed066905.json

interface FlutedLayerProps {
  slide: Slide;
  direction: Direction;
  /** Vertical ribs in the glass. */
  flutes: number;
  /** Called once the glass has cleared and the picture is whole. */
  onSettled: () => void;
}

/** Seconds the arriving slide takes to cross the frame. */
const SLIDE_SECONDS = 0.9;
/** When the glass starts to clear, as a share of the slide. */
const CLEAR_START = 0.55;
/** Seconds between one rib clearing and the next. */
const CLEAR_STAGGER = 0.022;
/** Seconds each rib takes to clear. */
const CLEAR_SECONDS = 0.62;

/** How much each rib magnifies its slice, like a lens, before it clears. */
const RIB_ZOOM = 1.22;
/** Pixels each slice is pushed against the travel, as the glass bends it. */
const RIB_SHIFT = 10;

const SLIDE_EASE = [0.65, 0, 0.35, 1] as const;
const CLEAR_EASE = [0.22, 1, 0.36, 1] as const;

/** Light down one side of each rib and shade down the other. */
const RIB_SHEEN =
  "linear-gradient(90deg, rgb(255 255 255 / 0.32), rgb(255 255 255 / 0) 36%, rgb(0 0 0 / 0) 64%, rgb(0 0 0 / 0.22))";

function Rib({
  slide,
  index,
  flutes,
  direction,
  delay,
  onCleared,
}: {
  slide: Slide;
  index: number;
  flutes: number;
  direction: Direction;
  delay: number;
  onCleared?: () => void;
}) {
  const left = (index / flutes) * 100;
  const right = ((flutes - index - 1) / flutes) * 100;
  const center = ((index + 0.5) / flutes) * 100;
  const transition = { delay, duration: CLEAR_SECONDS, ease: CLEAR_EASE };

  return (
    <div
      className="absolute inset-0"
      style={{ clipPath: `inset(0 ${right}% 0 ${left}%)` }}
    >
      {/* biome-ignore lint/performance/noImgElement: framework-agnostic registry block */}
      <motion.img
        alt=""
        animate={{ x: 0, scaleX: 1 }}
        className="absolute inset-0 size-full object-cover will-change-transform"
        decoding="async"
        draggable={false}
        height={slide.height}
        initial={{ x: -direction * RIB_SHIFT, scaleX: RIB_ZOOM }}
        onAnimationComplete={onCleared}
        src={slide.src}
        style={{ transformOrigin: `${center}% 50%` }}
        transition={transition}
        width={slide.width}
      />
      <motion.span
        animate={{ opacity: 0 }}
        className="absolute inset-y-0"
        initial={{ opacity: 1 }}
        style={{
          left: `${left}%`,
          right: `${right}%`,
          backgroundImage: RIB_SHEEN,
        }}
        transition={transition}
      />
    </div>
  );
}

/**
 * The arriving slide, seen through a sheet of fluted glass. It slides in cut
 * into vertical ribs, each showing its own slice magnified and pushed aside
 * the way ribbed glass bends light, with light down one edge and shade down
 * the other. Once it lands, the ribs ease back one after another, starting
 * from the side it came from, until the slices meet as one clear picture.
 * With reduced motion it fades in instead.
 */
export function FlutedLayer({
  slide,
  direction,
  flutes,
  onSettled,
}: FlutedLayerProps) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return (
      // biome-ignore lint/performance/noImgElement: framework-agnostic registry block
      <motion.img
        alt=""
        animate={{ opacity: 1 }}
        className="absolute inset-0 size-full object-cover"
        height={slide.height}
        initial={{ opacity: 0 }}
        onAnimationComplete={onSettled}
        src={slide.src}
        transition={{ duration: 0.35 }}
        width={slide.width}
      />
    );
  }

  const ribs = Array.from({ length: flutes }, (_, rib) => rib);
  const clearFrom = SLIDE_SECONDS * CLEAR_START;

  return (
    <motion.div
      animate={{ x: "0%" }}
      aria-hidden="true"
      className="absolute inset-0"
      initial={{ x: `${direction * 100}%` }}
      transition={{ duration: SLIDE_SECONDS, ease: SLIDE_EASE }}
    >
      {ribs.map((rib) => {
        // The ribs clear in the order the slide travels.
        const order = direction === 1 ? rib : flutes - 1 - rib;
        return (
          <Rib
            delay={clearFrom + order * CLEAR_STAGGER}
            direction={direction}
            flutes={flutes}
            index={rib}
            key={rib}
            onCleared={order === flutes - 1 ? onSettled : undefined}
            slide={slide}
          />
        );
      })}
    </motion.div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import type { Slide } from "./slides";

// Cortexcn item "gallery-fluted-glass-01", revision 1290ed066905, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-fluted-glass-01/1290ed066905.json

function pad(value: number) {
  return String(value).padStart(2, "0");
}

/**
 * The slide's number, title, and one line about it, over the picture. The
 * words change as soon as a new slide is picked, while its glass clears.
 */
export function SlideCaption({
  slide,
  index,
  count,
}: {
  slide: Slide;
  index: number;
  count: number;
}) {
  return (
    <div className="min-w-0 text-white">
      <p className="font-mono text-white/70 text-xs tabular-nums">
        {pad(index + 1)} / {pad(count)}
      </p>
      <AnimatePresence initial={false} mode="wait">
        <motion.div
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -6 }}
          initial={{ opacity: 0, y: 8 }}
          key={slide.src}
          transition={{ duration: 0.28, ease: "easeOut" }}
        >
          <p className="mt-1.5 truncate font-medium text-lg tracking-tight sm:text-2xl">
            {slide.title}
          </p>
          <p className="mt-1 hidden truncate text-sm text-white/75 sm:block">
            {slide.caption}
          </p>
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

"use client";

import { ChevronLeft, ChevronRight, Pause, Play } from "lucide-react";
import { Button } from "@/components/ui/button";

// Cortexcn item "gallery-fluted-glass-01", revision 1290ed066905, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-fluted-glass-01/1290ed066905.json

/** Round glassy buttons that read on any picture, in either theme. */
const glassButton =
  "rounded-full border-white/25 bg-black/25 text-white backdrop-blur-md hover:bg-black/45 hover:text-white dark:border-white/25 dark:bg-black/25 dark:hover:bg-black/45";

/**
 * Play or pause, then previous and next. The pause button only shows when
 * the slideshow plays on its own.
 */
export function SlideControls({
  autoplay,
  paused,
  onTogglePause,
  onPrevious,
  onNext,
}: {
  autoplay: boolean;
  paused: boolean;
  onTogglePause: () => void;
  onPrevious: () => void;
  onNext: () => void;
}) {
  return (
    <div className="flex shrink-0 items-center gap-2">
      {autoplay ? (
        <Button
          aria-label={paused ? "Play slideshow" : "Pause slideshow"}
          className={glassButton}
          onClick={onTogglePause}
          size="icon"
          variant="outline"
        >
          {paused ? <Play /> : <Pause />}
        </Button>
      ) : null}
      <Button
        aria-label="Previous slide"
        className={glassButton}
        onClick={onPrevious}
        size="icon"
        variant="outline"
      >
        <ChevronLeft />
      </Button>
      <Button
        aria-label="Next slide"
        className={glassButton}
        onClick={onNext}
        size="icon"
        variant="outline"
      >
        <ChevronRight />
      </Button>
    </div>
  );
}

"use client";

import { type AnimationPlaybackControls, useAnimate } from "motion/react";
import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import type { Slide } from "./slides";

// Cortexcn item "gallery-fluted-glass-01", revision 1290ed066905, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-fluted-glass-01/1290ed066905.json

/**
 * The bar of the slide on screen, filling while it plays. It pauses where it
 * is, and when it is full the slideshow moves on.
 */
function PlayingFill({
  seconds,
  playing,
  onDone,
}: {
  seconds: number;
  playing: boolean;
  onDone: () => void;
}) {
  const [scope, animate] = useAnimate<HTMLSpanElement>();
  const controls = useRef<AnimationPlaybackControls | null>(null);
  const done = useRef(onDone);
  done.current = onDone;

  useEffect(() => {
    const playback = animate(
      scope.current,
      { scaleX: [0, 1] },
      { duration: seconds, ease: "linear", onComplete: () => done.current() },
    );
    controls.current = playback;
    return () => playback.stop();
  }, [animate, scope, seconds]);

  useEffect(() => {
    if (playing) {
      controls.current?.play();
    } else {
      controls.current?.pause();
    }
  }, [playing]);

  return (
    <span
      className="absolute inset-0 origin-left rounded-full bg-white"
      ref={scope}
      // A transform, not a scale class, since the animation drives `transform`.
      style={{ transform: "scaleX(0)" }}
    />
  );
}

/**
 * One bar per slide that also picks it: the ones already seen are full, the
 * one on screen fills while the slideshow plays, and the rest are empty.
 */
export function SlideProgress({
  slides,
  current,
  autoplay,
  playing,
  seconds,
  onSelect,
  onDone,
}: {
  slides: Slide[];
  current: number;
  autoplay: boolean;
  playing: boolean;
  seconds: number;
  onSelect: (index: number) => void;
  onDone: () => void;
}) {
  return (
    <div className="flex items-center gap-1.5">
      {slides.map((slide, index) => {
        const isCurrent = index === current;
        return (
          <button
            aria-current={isCurrent ? "true" : undefined}
            aria-label={`Show slide ${index + 1}, ${slide.title}`}
            className="group/bar flex h-6 flex-1 items-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-white/80"
            key={slide.src}
            onClick={() => onSelect(index)}
            type="button"
          >
            <span className="relative h-1 w-full overflow-hidden rounded-full bg-white/30 transition-colors group-hover/bar:bg-white/45">
              {isCurrent && autoplay ? (
                <PlayingFill
                  key={current}
                  onDone={onDone}
                  playing={playing}
                  seconds={seconds}
                />
              ) : (
                <span
                  className={cn(
                    "absolute inset-0 origin-left rounded-full bg-white transition-transform duration-300",
                    index <= current ? "scale-x-100" : "scale-x-0",
                  )}
                />
              )}
            </span>
          </button>
        );
      })}
    </div>
  );
}

export interface Slide {
  src: string;
  /** Describes the picture for screen readers. */
  alt: string;
  title: string;
  caption: string;
  /** The picture's size, so the browser can reserve its space. */
  width: number;
  height: number;
}

